@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    // ── State ──
    private List<Channel>? _channels;
    private Channel? _activeChannel;
    private int? _activeChannelId;
    private List<Message>? _messages;
    private int _messageSkip;
    private bool _hasMoreMessages = true;
    private bool _loadingMore;

    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private string _newMessageText = "";
    private string _threadReplyText = "";

    // Reply counts keyed by root message id
    private Dictionary<int, int> _replyCounts = new();

    // Element references for JS scroll interop
    private ElementReference _messageListRef;
    private ElementReference _threadListRef;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<Chat>? _dotNetRef;

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./Components/Pages/Chat.razor.js");
            _dotNetRef = DotNetObjectReference.Create(this);
        }
    }

    public async ValueTask DisposeAsync()
    {
        _dotNetRef?.Dispose();
        if (_jsModule is not null)
        {
            await _jsModule.DisposeAsync();
        }
    }

    // ── Channel Selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id) return;

        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = null;
        _messageSkip = 0;
        _hasMoreMessages = true;
        _replyCounts.Clear();
        _emojiPickerMessageId = null;
        CloseThread();

        var msgs = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = msgs;
        _messageSkip = msgs.Count;
        _hasMoreMessages = msgs.Count == PageSize;

        BuildReplyCounts();

        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannels();

        // Allow render to complete, then scroll and register handler
        await InvokeAsync(StateHasChanged);
        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
            await _jsModule.InvokeVoidAsync("registerScrollTopCallback", _messageListRef, _dotNetRef);
        }
    }

    // ── Pagination ──

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingMore || !_hasMoreMessages || _activeChannelId is null) return;

        _loadingMore = true;
        await InvokeAsync(StateHasChanged);

        double prevHeight = 0;
        if (_jsModule is not null)
        {
            prevHeight = await _jsModule.InvokeAsync<double>("getScrollHeight", _messageListRef);
        }

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages = [..older, ..(_messages ?? [])];
            _messageSkip += older.Count;
            BuildReplyCounts();
        }
        _hasMoreMessages = older.Count == PageSize;
        _loadingMore = false;

        await InvokeAsync(StateHasChanged);
        await Task.Yield();
        if (_jsModule is not null && prevHeight > 0)
        {
            await _jsModule.InvokeVoidAsync("maintainScrollPosition", _messageListRef, prevHeight);
        }
    }

    // ── Sending Messages ──

    private async Task SendMainMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= [];
        _messages.Add(sent);
        _messageSkip++;
        _newMessageText = "";

        await InvokeAsync(StateHasChanged);
        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
        }
    }

    private async Task HandleMainKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMainMessageAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
        _emojiPickerMessageId = null;

        await InvokeAsync(StateHasChanged);
        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _threadListRef);
        }
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
        _threadMessages ??= [];
        _threadMessages.Add(reply);
        _threadReplyText = "";

        // Update reply count
        _replyCounts[_threadRootId.Value] = _threadMessages.Count;

        await InvokeAsync(StateHasChanged);
        await Task.Yield();
        if (_jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _threadListRef);
        }
    }

    private async Task HandleThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh the affected message list
        if (_activeChannelId is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messageSkip);
            BuildReplyCounts();
        }
        if (_threadRootId is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootId.Value);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Helpers ──

    private void BuildReplyCounts()
    {
        if (_messages is null) return;
        // Messages with ReplyToId point to their root; count them
        var roots = _messages.Where(m => m.ReplyToId is null).Select(m => m.Id).ToHashSet();
        foreach (var id in roots)
        {
            _replyCounts[id] = _messages.Count(m => m.ReplyToId == id);
        }
    }

    private int GetReplyCount(int messageId) =>
        _replyCounts.TryGetValue(messageId, out var c) ? c : 0;

    private async Task RefreshChannels()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private static string Truncate(string text, int max) =>
        text.Length <= max ? text : text[..(max - 1)] + "…";

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}
